using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests;

/// <summary>
/// Shared helpers for creating in-memory SchoolContext instances and seeding test data.
/// </summary>
public static class TestHelpers
{
    /// <summary>
    /// Creates a fresh in-memory SchoolContext with a unique database name.
    /// </summary>
    public static SchoolContext CreateInMemoryContext()
    {
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
            .Options;

        var context = new SchoolContext(options);
        context.Database.EnsureCreated();
        return context;
    }

    /// <summary>
    /// Seeds a context with a standard set of test data (students, instructors, departments, courses, enrollments).
    /// </summary>
    public static void SeedTestData(SchoolContext context)
    {
        var instructor1 = new Instructor
        {
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = DateTime.Parse("1995-03-11"),
            CourseAssignments = new List<CourseAssignment>()
        };
        var instructor2 = new Instructor
        {
            FirstMidName = "Fadi",
            LastName = "Fakhouri",
            HireDate = DateTime.Parse("2002-07-06"),
            CourseAssignments = new List<CourseAssignment>()
        };

        context.Instructors.AddRange(instructor1, instructor2);
        context.SaveChanges();

        var dept1 = new Department
        {
            Name = "English",
            Budget = 350000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = instructor1.ID
        };
        var dept2 = new Department
        {
            Name = "Mathematics",
            Budget = 100000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = instructor2.ID
        };

        context.Departments.AddRange(dept1, dept2);
        context.SaveChanges();

        var course1 = new Course
        {
            CourseID = 2021,
            Title = "Composition",
            Credits = 3,
            DepartmentID = dept1.DepartmentID,
            Enrollments = new List<Enrollment>(),
            CourseAssignments = new List<CourseAssignment>()
        };
        var course2 = new Course
        {
            CourseID = 1045,
            Title = "Calculus",
            Credits = 4,
            DepartmentID = dept2.DepartmentID,
            Enrollments = new List<Enrollment>(),
            CourseAssignments = new List<CourseAssignment>()
        };

        context.Courses.AddRange(course1, course2);
        context.SaveChanges();

        var student1 = new Student
        {
            FirstMidName = "Carson",
            LastName = "Alexander",
            EnrollmentDate = DateTime.Parse("2010-09-01"),
            Enrollments = new List<Enrollment>()
        };
        var student2 = new Student
        {
            FirstMidName = "Meredith",
            LastName = "Alonso",
            EnrollmentDate = DateTime.Parse("2012-09-01"),
            Enrollments = new List<Enrollment>()
        };
        var student3 = new Student
        {
            FirstMidName = "Arturo",
            LastName = "Anand",
            EnrollmentDate = DateTime.Parse("2013-09-01"),
            Enrollments = new List<Enrollment>()
        };

        context.Students.AddRange(student1, student2, student3);
        context.SaveChanges();

        context.Enrollments.AddRange(
            new Enrollment { StudentID = student1.ID, CourseID = course1.CourseID, Grade = Grade.A },
            new Enrollment { StudentID = student2.ID, CourseID = course2.CourseID, Grade = Grade.B }
        );
        context.SaveChanges();

        // Add course assignments
        context.CourseAssignments.Add(new CourseAssignment
        {
            CourseID = course1.CourseID,
            InstructorID = instructor1.ID
        });
        context.SaveChanges();
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        // Drain any leftover notifications from previous tests (shared static queue)
        _sut = new NotificationService();
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain queue so static state doesn't leak across tests
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotification()
    {
        // Act
        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "Admin");

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("Student", received.EntityType);
        Assert.Equal("42", received.EntityId);
        Assert.Equal("CREATE", received.Operation);
        Assert.Equal("Admin", received.CreatedBy);
        Assert.False(received.IsRead);
        Assert.Contains("Student 'John Doe'", received.Message);
        Assert.Contains("created", received.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        // Act
        _sut.SendNotification("Course", "101", EntityOperation.UPDATE);

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Contains("Course (ID: 101)", received.Message);
        Assert.Contains("updated", received.Message);
    }

    [Fact]
    public void SendNotification_DeleteOperation_MessageContainsDeleted()
    {
        // Act
        _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "TestUser");

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("DELETE", received.Operation);
        Assert.Contains("deleted", received.Message);
        Assert.Contains("Department 'Engineering'", received.Message);
    }

    [Fact]
    public void SendNotification_DefaultUserName_IsSystem()
    {
        // Act
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("System", received.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        // Arrange
        var before = DateTime.Now.AddSeconds(-1);

        // Act
        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.True(received.CreatedAt >= before, $"CreatedAt {received.CreatedAt} should be >= {before}");
        Assert.True(received.CreatedAt <= DateTime.Now.AddSeconds(1));
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Act
        var result = _sut.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_FifoOrder()
    {
        // Arrange
        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);

        // Act & Assert - FIFO
        var first = _sut.ReceiveNotification();
        Assert.NotNull(first);
        Assert.Equal("A", first.EntityType);
        Assert.Equal("1", first.EntityId);

        var second = _sut.ReceiveNotification();
        Assert.NotNull(second);
        Assert.Equal("B", second.EntityType);
        Assert.Equal("2", second.EntityId);
    }

    [Fact]
    public void ReceiveNotification_DequeuedItemNotAvailableAgain()
    {
        // Arrange
        _sut.SendNotification("X", "1", EntityOperation.CREATE);
        _sut.ReceiveNotification(); // consume it

        // Act
        var result = _sut.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op in the in-memory implementation but should not throw
        var ex = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_UpdateOperation_MessageContainsUpdated()
    {
        // Act
        _sut.SendNotification("Instructor", "7", "Jane Smith", EntityOperation.UPDATE, "Admin");

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("UPDATE", received.Operation);
        Assert.Contains("updated", received.Message);
        Assert.Contains("Instructor 'Jane Smith'", received.Message);
        Assert.Equal("Admin", received.CreatedBy);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var ex = Record.Exception(() => service.Dispose());
        Assert.Null(ex);
    }
}

using Xunit;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_FirstPage_ContainsCorrectItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_LastPage_ContainsRemainingItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        // Assert
        Assert.Equal(5, result.Count);
        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }

    [Fact]
    public void Create_MiddlePage_ContainsCorrectSlice()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(11, result[0]);
        Assert.Equal(20, result[9]);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();
        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();
        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_FirstPage_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_SingleItem_SinglePage()
    {
        var source = new[] { 42 }.AsQueryable();
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Single(result);
        Assert.Equal(1, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
        Assert.Equal(42, result[0]);
    }

    [Fact]
    public void Create_EmptySource_EmptyPage()
    {
        var source = Enumerable.Empty<int>().AsQueryable();
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
    }

    [Fact]
    public void TotalPages_ExactMultiple_CalculatesCorrectly()
    {
        // 20 items, pageSize 10 => exactly 2 pages
        var source = Enumerable.Range(1, 20).AsQueryable();
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(2, result.TotalPages);
    }

    [Fact]
    public void Constructor_SetsPropertiesCorrectly()
    {
        var items = new List<string> { "a", "b", "c" };
        var list = new PaginatedList<string>(items, count: 30, pageIndex: 3, pageSize: 10);

        Assert.Equal(3, list.PageIndex);
        Assert.Equal(3, list.TotalPages);
        Assert.Equal(3, list.Count);
        Assert.Equal("a", list[0]);
        Assert.Equal("b", list[1]);
        Assert.Equal("c", list[2]);
    }
}

