using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new NotificationsController(_context);

        // Drain the static queue before each test
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain after test too
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsView()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithZeroCount()
    {
        var result = _controller.GetNotifications();

        Assert.IsType<JsonResult>(result);
        var value = result.Value;
        Assert.NotNull(value);

        // Use reflection to check the anonymous object properties
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");
        Assert.NotNull(successProp);
        Assert.NotNull(countProp);
        Assert.True((bool)successProp.GetValue(value)!);
        Assert.Equal(0, (int)countProp.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotificationsInResult()
    {
        // Arrange - enqueue a notification via the service
        var svc = new NotificationService();
        svc.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "Admin");

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var value = result.Value!;
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");
        var notifProp = value.GetType().GetProperty("notifications");

        Assert.True((bool)successProp!.GetValue(value)!);
        Assert.Equal(1, (int)countProp!.GetValue(value)!);

        var notifications = notifProp!.GetValue(value) as List<Notification>;
        Assert.NotNull(notifications);
        Assert.Single(notifications);
        Assert.Equal("Student", notifications[0].EntityType);
        Assert.Equal("1", notifications[0].EntityId);
        Assert.Contains("Test Student", notifications[0].Message);
    }

    [Fact]
    public void GetNotifications_LimitsToTen()
    {
        // Arrange - enqueue 15 notifications
        var svc = new NotificationService();
        for (int i = 0; i < 15; i++)
        {
            svc.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
        }

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var value = result.Value!;
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(10, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccessJson()
    {
        var result = _controller.MarkAsRead(1);

        Assert.IsType<JsonResult>(result);
        var value = result.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);
    }
}

