using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        // Drain any leftover notifications from previous tests (shared static queue)
        _sut = new NotificationService();
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain queue so static state doesn't leak across tests
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotification()
    {
        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "Admin");

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("Student", received.EntityType);
        Assert.Equal("42", received.EntityId);
        Assert.Equal("CREATE", received.Operation);
        Assert.Equal("Admin", received.CreatedBy);
        Assert.False(received.IsRead);
        Assert.Contains("Student 'John Doe'", received.Message);
        Assert.Contains("created", received.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        _sut.SendNotification("Course", "101", EntityOperation.UPDATE);

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Contains("Course (ID: 101)", received.Message);
        Assert.Contains("updated", received.Message);
    }

    [Fact]
    public void SendNotification_DeleteOperation_MessageContainsDeleted()
    {
        _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "TestUser");

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("DELETE", received.Operation);
        Assert.Contains("deleted", received.Message);
        Assert.Contains("Department 'Engineering'", received.Message);
    }

    [Fact]
    public void SendNotification_DefaultUserName_IsSystem()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("System", received.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        var before = DateTime.Now.AddSeconds(-1);

        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.True(received.CreatedAt >= before, $"CreatedAt {received.CreatedAt} should be >= {before}");
        Assert.True(received.CreatedAt <= DateTime.Now.AddSeconds(1));
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_FifoOrder()
    {
        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);

        var first = _sut.ReceiveNotification();
        Assert.NotNull(first);
        Assert.Equal("A", first.EntityType);
        Assert.Equal("1", first.EntityId);

        var second = _sut.ReceiveNotification();
        Assert.NotNull(second);
        Assert.Equal("B", second.EntityType);
        Assert.Equal("2", second.EntityId);
    }

    [Fact]
    public void ReceiveNotification_DequeuedItemNotAvailableAgain()
    {
        _sut.SendNotification("X", "1", EntityOperation.CREATE);
        _sut.ReceiveNotification(); // consume it

        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var ex = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_UpdateOperation_MessageContainsUpdated()
    {
        _sut.SendNotification("Instructor", "7", "Jane Smith", EntityOperation.UPDATE, "Admin");

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("UPDATE", received.Operation);
        Assert.Contains("updated", received.Message);
        Assert.Contains("Instructor 'Jane Smith'", received.Message);
        Assert.Equal("Admin", received.CreatedBy);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var ex = Record.Exception(() => service.Dispose());
        Assert.Null(ex);
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        TestHelpers.SeedTestData(_context);
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // --- Index ---

    [Fact]
    public void Index_NoParams_ReturnsViewWithAllStudents()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Anand", model[2].LastName);
    }

    [Fact]
    public void Index_NameDescSort_OrdersByLastNameDescending()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Anand", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Alexander", model[2].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Anand", model[2].LastName);
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Anand", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Alexander", model[2].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersStudents()
    {
        var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersCorrectly()
    {
        var result = _controller.Index(null, null, "Carson", null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Carson", model[0].FirstMidName);
    }

    [Fact]
    public void Index_SearchStringResetsPage_ToOne()
    {
        var result = _controller.Index(null, null, "A", 5) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearchString_UsesCurrentFilter()
    {
        var result = _controller.Index(null, "Alexander", null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SetsViewBagProperties()
    {
        _controller.Index("Date", null, "test", null);

        Assert.Equal("Date", _controller.ViewBag.CurrentSort);
        Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
        Assert.Equal("", _controller.ViewBag.NameSortParm);
        Assert.Equal("test", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Index_EmptySortOrder_SetsNameSortParmToNameDesc()
    {
        _controller.Index(null, null, null, null);

        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        var student = _context.Students.First();
        var result = _controller.Details(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
        Assert.Equal(student.LastName, model.LastName);
        Assert.Equal(student.FirstMidName, model.FirstMidName);
    }

    [Fact]
    public void Details_ValidId_IncludesEnrollments()
    {
        var student = _context.Students.First(s => s.LastName == "Alexander");
        var result = _controller.Details(student.ID) as ViewResult;

        var model = Assert.IsType<Student>(result!.Model);
        Assert.NotNull(model.Enrollments);
        Assert.NotEmpty(model.Enrollments);
    }

    // --- Create GET ---

    [Fact]
    public void Create_Get_ReturnsViewWithStudentDefaultDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    // --- Create POST ---

    [Fact]
    public void CreatePost_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void CreatePost_ValidStudent_AddsToDatabase()
    {
        var initialCount = _context.Students.Count();
        var student = new Student
        {
            FirstMidName = "New",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        _controller.Create(student);

        Assert.Equal(initialCount + 1, _context.Students.Count());
        var added = _context.Students.First(s => s.LastName == "Student");
        Assert.Equal("New", added.FirstMidName);
        Assert.Equal(new DateTime(2023, 9, 1), added.EnrollmentDate);
    }

    [Fact]
    public void CreatePost_DefaultEnrollmentDate_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void CreatePost_EnrollmentDateBefore1753_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void CreatePost_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "",
            EnrollmentDate = new DateTime(2023, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.Same(student, result.Model);
    }

    // --- Edit GET ---

    [Fact]
    public void Edit_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_ValidId_ReturnsViewWithStudent()
    {
        var student = _context.Students.First();
        var result = _controller.Edit(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
        Assert.Equal(student.LastName, model.LastName);
    }

    [Fact]
    public void Edit_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    // --- Edit POST ---

    [Fact]
    public void EditPost_ValidStudent_RedirectsToIndex()
    {
        var student = _context.Students.AsNoTracking().First();
        student.LastName = "Updated";
        student.EnrollmentDate = new DateTime(2023, 1, 15);

        var result = _controller.Edit(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void EditPost_ValidStudent_UpdatesDatabase()
    {
