        var originalId = student.ID;
        student.LastName = "ModifiedLastName";
        student.EnrollmentDate = new DateTime(2023, 6, 15);

        _controller.Edit(student);

        var updated = _context.Students.AsNoTracking().First(s => s.ID == originalId);
