namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        TestHelpers.SeedTestData(_context);
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockEnv.Setup(e => e.WebRootPath).Returns(Path.Combine(Path.GetTempPath(), "wwwroot"));
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // --- Index ---

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_CoursesHaveDepartmentIDs()
    {
        var result = _controller.Index() as ViewResult;
        var model = Assert.IsAssignableFrom<List<Course>>(result!.Model);

        Assert.All(model, c => Assert.True(c.DepartmentID > 0));
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        var course = _context.Courses.First();

        var result = _controller.Details(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
        Assert.Equal(course.Title, model.Title);
        Assert.Equal(course.Credits, model.Credits);
    }

    // --- Create GET ---

    [Fact]
    public void Create_Get_ReturnsViewWithCourseModel()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.IsType<Course>(result.Model);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    // --- Create POST ---

    [Fact]
    public void CreatePost_ValidCourse_NoImage_RedirectsToIndex()
    {
        var course = new Course
        {
            CourseID = 9999,
            Title = "New Course",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        var result = _controller.Create(course, null);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void CreatePost_ValidCourse_NoImage_AddsToDatabase()
    {
        var deptId = _context.Departments.First().DepartmentID;
        var course = new Course
        {
            CourseID = 8888,
            Title = "Added Course",
            Credits = 4,
            DepartmentID = deptId
        };

        _controller.Create(course, null);

        var added = _context.Courses.Find(8888);
        Assert.NotNull(added);
        Assert.Equal("Added Course", added.Title);
        Assert.Equal(4, added.Credits);
        Assert.Equal(deptId, added.DepartmentID);
    }

    [Fact]
    public void CreatePost_InvalidModelState_ReturnsViewWithCourse()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 7777, Credits = 3 };

        var result = _controller.Create(course, null) as ViewResult;

        Assert.NotNull(result);
        Assert.Same(course, result.Model);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
