using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        // Drain any leftover notifications from previous tests (shared static queue)
        _sut = new NotificationService();
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain queue so static state doesn't leak across tests
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotification()
    {
        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "Admin");

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("Student", received.EntityType);
        Assert.Equal("42", received.EntityId);
        Assert.Equal("CREATE", received.Operation);
        Assert.Equal("Admin", received.CreatedBy);
        Assert.False(received.IsRead);
        Assert.Contains("Student 'John Doe'", received.Message);
        Assert.Contains("created", received.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        _sut.SendNotification("Course", "101", EntityOperation.UPDATE);

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Contains("Course (ID: 101)", received.Message);
        Assert.Contains("updated", received.Message);
    }

    [Fact]
    public void SendNotification_DeleteOperation_MessageContainsDeleted()
    {
        _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "TestUser");

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("DELETE", received.Operation);
        Assert.Contains("deleted", received.Message);
        Assert.Contains("Department 'Engineering'", received.Message);
    }

    [Fact]
    public void SendNotification_DefaultUserName_IsSystem()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("System", received.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        var before = DateTime.Now.AddSeconds(-1);

        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.True(received.CreatedAt >= before, $"CreatedAt {received.CreatedAt} should be >= {before}");
        Assert.True(received.CreatedAt <= DateTime.Now.AddSeconds(1));
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_FifoOrder()
    {
        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);

        var first = _sut.ReceiveNotification();
        Assert.NotNull(first);
        Assert.Equal("A", first.EntityType);
        Assert.Equal("1", first.EntityId);

        var second = _sut.ReceiveNotification();
        Assert.NotNull(second);
        Assert.Equal("B", second.EntityType);
        Assert.Equal("2", second.EntityId);
    }

    [Fact]
    public void ReceiveNotification_DequeuedItemNotAvailableAgain()
    {
        _sut.SendNotification("X", "1", EntityOperation.CREATE);
        _sut.ReceiveNotification(); // consume it

        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var ex = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_UpdateOperation_MessageContainsUpdated()
    {
        _sut.SendNotification("Instructor", "7", "Jane Smith", EntityOperation.UPDATE, "Admin");

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("UPDATE", received.Operation);
        Assert.Contains("updated", received.Message);
        Assert.Contains("Instructor 'Jane Smith'", received.Message);
        Assert.Equal("Admin", received.CreatedBy);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var ex = Record.Exception(() => service.Dispose());
        Assert.Null(ex);
    }
}

