        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(initialCount - 1, _context.Instructors.Count());
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsAdmin_NullsDepartmentAdministrator()
    {
        var dept = _context.Departments.First();
        var instructorId = dept.InstructorID!.Value;

        // Add office assignment since DeleteConfirmed requires it
        if (!_context.OfficeAssignments.Any(o => o.InstructorID == instructorId))
        {
            _context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = instructorId,
                Location = "Admin Office"
            });
            _context.SaveChanges();
        }

        _controller.DeleteConfirmed(instructorId);

        var updatedDept = _context.Departments.AsNoTracking().First(d => d.DepartmentID == dept.DepartmentID);
        Assert.Null(updatedDept.InstructorID);
    }
}

