public void DeleteConfirmed_RemovesInstructorAndRedirects()
{
    // Add a third instructor that is NOT an administrator of any department
    var extraInstructor = new Instructor
    {
        FirstMidName = "Extra",
        LastName = "NoAdmin",
        HireDate = new DateTime(2020, 1, 1),
        CourseAssignments = new List<CourseAssignment>()
    };
    _context.Instructors.Add(extraInstructor);
    _context.SaveChanges();

    // Add OfficeAssignment since DeleteConfirmed includes it
    _context.OfficeAssignments.Add(new OfficeAssignment
    {
        InstructorID = extraInstructor.ID,
        Location = "Test Office"
    });
    _context.SaveChanges();

    var initialCount = _context.Instructors.Count();

    var result = _controller.DeleteConfirmed(extraInstructor.ID);

    var redirect = Assert.IsType<RedirectToActionResult>(result);
    Assert.Equal("Index", redirect.ActionName);
    Assert.Equal(initialCount - 1, _context.Instructors.Count());
}

